-- Public copy is additive. Internal activity/access/story rules are untouched.
with copy as (select $copy${"archive research":"Look through the records for a clue or a forgotten connection.","research":"Explore a question together and compare your findings.","people watching":"Watch the passing crowd and compare impressions.","drinks":"Share a drink and an unhurried conversation.","shopping":"Browse the stalls and look for something worth bringing home.","music":"Listen together and trade favorite songs.","recovery":"Take things slowly and make room to rest.","food":"Share something to eat and take a break.","street food":"Try a bite from the street vendors.","massage":"Arrange a massage and a little time to unwind.","lodging":"Arrange a place to stay.","local conversation":"Get to know the people who spend time here.","repairs":"Bring something that needs mending.","travel":"Plan your next journey.","fishing":"Set aside time by the water to fish.","worship":"Attend a service or spend a moment in reflection.","confession":"Speak privately about something weighing on you.","archive study":"Spend time with the records and compare what you find.","training":"Practice a skill together.","games":"Choose a game and enjoy a little friendly competition.","strategy councils":"Discuss a plan and weigh the alternatives.","formal dining":"Arrange a dinner with a little ceremony.","petitions":"Put a request into words and seek a hearing.","weather watching":"Watch the sky and compare signs of a change.","route planning":"Compare routes and prepare for the journey.","memorial visits":"Visit a memorial and share what it means to you.","private conversation":"Find time for a conversation away from the crowd.","bathing":"Plan a relaxing soak together.","wine tasting":"Compare flavors and choose a favorite wine.","medical care":"Seek care and discuss what would help.","private dinners":"Plan a quiet dinner for two.","trade":"Compare goods and negotiate an exchange.","observation":"Take a closer look at your surroundings.","feasts":"Plan to share a feast.","diplomacy":"Explore a disagreement and possible common ground.","produce trade":"Browse the harvest and compare produce.","herbs":"Browse herbs and ask about their uses.","crafts":"Browse handmade work and talk about how it is made.","rumor exchange":"Trade rumors and decide which ones deserve a closer look.","masked balls":"Plan an evening of masks, music, and conversation.","ruin exploration":"Plan an expedition to examine what remains.","royal audiences":"Seek an audience to present a request.","court intrigue":"Compare loyalties and the rumors moving through court.","formal feasts":"Arrange to attend a formal feast.","gossip":"Compare the stories circulating around town.","private negotiation":"Discuss terms away from the public eye.","salon debate":"Join a discussion of ideas, loyalties, and disagreements.","market stalls":"Compare what the vendors have brought to market.","memorials":"Remember someone and listen to the stories they left behind.","banking":"Discuss savings, payments, or a financial arrangement.","contract review":"Read through an agreement and discuss its terms.","genealogy research":"Trace a family connection through the records.","ale":"Compare ales over a conversation.","hot meals":"Sit down over a warm meal.","dice":"Play a round of dice.","veteran gossip":"Listen to stories from those who have served.","mutual aid":"Find a practical way to help someone.","smithing":"Discuss a piece of metalwork with a smith.","weapon inspection":"Examine the workmanship and condition of a weapon.","camp trade":"See what supplies are changing hands in camp.","letters":"Write a letter or arrange for one to be delivered.","dragon care":"Discuss the work of tending a dragon.","egg study":"Examine what is known about the eggs.","ritual observation":"Arrange to witness a ritual.","political conversation":"Compare views on the people and decisions shaping the realm.","street performance":"Stop to watch a performance.","cliff walks":"Plan a walk along the cliffs.","healing":"Arrange care for an injury or a difficult recovery.","meals":"Make time for a meal together.","chance meetings":"Leave room for an unexpected conversation.","forest travel":"Plan a journey through the forest.","private vows":"Find words for a promise that matters to you.","meditation":"Set aside time to settle your thoughts.","quiet prayer":"Take a quiet moment for reflection.","genealogy":"Explore the branches of a family history.","legal petitions":"Prepare a request and decide how to present it.","apprenticeship":"Ask about learning a craft from someone experienced.","navigation":"Study the route and work out your next bearing.","sea songs":"Trade songs and stories from the sea.","crew gossip":"Catch up on the stories passing between crews.","tide monitoring":"Watch the tide and discuss the best time to travel.","herbal work":"Compare herbs and their traditional uses.","barter":"Find an exchange that works for both sides.","forging":"Plan a piece of metalwork.","information exchange":"Compare what each of you has learned.","community work":"Join a task that benefits the neighborhood.","shelter":"Arrange somewhere to rest and recover.","courier exchange":"Meet a courier to discuss a delivery.","scouting":"Discuss a scouting route and what to look for.","safe lodging":"Look for a secure place to spend the night.","debate":"Take opposite sides and see where the discussion leads.","message exchange":"Arrange to exchange a message.","ancient research":"Study traces of the past for something others have missed."}$copy$::jsonb as descriptions), enriched as (
 select l.id,jsonb_object_agg(a.activity,copy.descriptions->a.activity) as descriptions
 from public.together_locations l cross join copy cross join lateral unnest(l.possible_activities) a(activity)
 where copy.descriptions ? a.activity group by l.id
)
update public.together_locations l set canonical_lore=jsonb_set(coalesce(l.canonical_lore,'{}'::jsonb),'{activityDescriptions}',e.descriptions||coalesce(l.canonical_lore->'activityDescriptions','{}'::jsonb)),updated_at=now()
from enriched e where l.id=e.id;
